import test from 'node:test';
import assert from 'node:assert/strict';
import { MockFinanceDataService } from '../src/services/dataService.js';
import { createClassificationRule, upsertClassificationRule, applySavedClassificationRules } from '../src/services/classificationRules.js';
import { calculateSummary } from '../src/services/finance.js';

test('quick edit does not learn automatically, approved equivalent rule is reused',async()=>{const s=new MockFinanceDataService();s.classificationRules=[];const before=(await s.getTransactions()).find(t=>t.id==='t1');await s.updateTransaction('t1',{category:'בית',subcategory:'מטבח'});assert.equal(s.classificationRules.length,0);const rule=createClassificationRule({target:'expense',category:'בית',description:before.description,counterparty:before.merchant,sourceType:before.sourceType,direction:'outgoing',typicalAmount:before.amount});s.classificationRules=upsertClassificationRule(s.classificationRules,rule);s.classificationRules=upsertClassificationRule(s.classificationRules,rule);assert.equal(s.classificationRules.length,1);assert.equal(applySavedClassificationRules({merchant:before.merchant,description:before.description,sourceType:before.sourceType,direction:'debit',amount:before.amount},s.classificationRules).category,'בית');const saved=(await s.getTransactions()).find(t=>t.id==='t1');assert.equal(saved.id,'t1');assert.equal(saved.subcategory,'מטבח');assert.equal(saved.sourceType,before.sourceType)});
test('quick cash creates exactly one canonical expense with macro/micro category and totals impact',async()=>{const s=new MockFinanceDataService();const beforeRows=await s.getTransactions(),before=beforeRows.length;const tx=await s.createCashTransaction({merchant:'פלאפל',amount:35,date:'2026-08-22',category:'אוכל',subcategory:'אוכל בחוץ'});const all=await s.getTransactions();assert.equal(all.length,before+1);assert.equal(all.filter(t=>t.id===tx.id).length,1);assert.equal(tx.financialType,'expense');assert.equal(tx.sourceType,'manual_cash');assert.equal(tx.paymentMethod,'cash');assert.equal(tx.category,'אוכל');assert.equal(tx.subcategory,'אוכל בחוץ');assert.equal(calculateSummary(all).expenses,calculateSummary(beforeRows).expenses+35)});
